import java.util.*;

public class NQueens {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> result = new ArrayList<>();
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        // 三个冲突检测集合
        Set<Integer> cols = new HashSet<>();       // 已占用的列
        Set<Integer> diag1 = new HashSet<>();      // row - col，主对角线
        Set<Integer> diag2 = new HashSet<>();      // row + col，副对角线
        backtrack(result, board, 0, cols, diag1, diag2);
        return result;
    }

    private void backtrack(List<List<String>> result, char[][] board,
                           int row, Set<Integer> cols,
                           Set<Integer> diag1, Set<Integer> diag2) {
        int n = board.length;
        if (row == n) {                        // 所有行放满，收集解
            List<String> solution = new ArrayList<>();
            for (char[] r : board) solution.add(new String(r));
            result.add(solution);
            return;
        }
        for (int col = 0; col < n; col++) {
            // O(1) 冲突检查
            if (cols.contains(col)) continue;
            if (diag1.contains(row - col)) continue;
            if (diag2.contains(row + col)) continue;
            // 放置皇后
            board[row][col] = 'Q';
            cols.add(col);
            diag1.add(row - col);
            diag2.add(row + col);
            // 递归下一行
            backtrack(result, board, row + 1, cols, diag1, diag2);
            // 回溯：撤销
            board[row][col] = '.';
            cols.remove(col);
            diag1.remove(row - col);
            diag2.remove(row + col);
        }
    }
}

import java.util.*;

public class NQueensBitmask {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> result = new ArrayList<>();
        solve(result, n, 0, 0, 0, 0, new int[n]);
        return result;
    }

    // pos[row] = col 记录每行皇后所在列
    private void solve(List<List<String>> result, int n, int row,
                       int cols, int diag1, int diag2, int[] pos) {
        if (row == n) {
            List<String> board = new ArrayList<>();
            for (int r = 0; r < n; r++) {
                char[] line = new char[n];
                Arrays.fill(line, '.');
                line[pos[r]] = 'Q';
                board.add(new String(line));
            }
            result.add(board);
            return;
        }
        // available 中 1 的位表示可以放皇后的列
        int available = ((1 << n) - 1) & ~(cols | diag1 | diag2);
        while (available != 0) {
            int bit = available & (-available); // 取最低位的 1
            available -= bit;
            int col = Integer.bitCount(bit - 1); // 位转列号
            pos[row] = col;
            solve(result, n, row + 1,
                  cols | bit,                      // 占用列
                  (diag1 | bit) << 1,              // 主对角线左移
                  (diag2 | bit) >> 1,              // 副对角线右移
                  pos);
        }
    }
}
